Clase Libro
    Privado Definir prestado Como Entero;

    Metodo Constructor()
        Este.prestado <- 0;
    FinMetodo

    Publico Metodo Prestar()
        Este.prestado <- 1;
    FinMetodo

    Publico Metodo Devolver()
        Este.prestado <- 0;
    FinMetodo

    Publico Metodo EstaPrestado() Como Entero
        Retornar Este.prestado;
    FinMetodo
FinClase

Proceso EjecutarLibro
    Definir prestar Como Entero;
    Definir devolver Como Entero;
    Definir libro Como Libro;
    Leer prestar;
    Leer devolver;
    libro <- Nuevo Libro();
    Si prestar = 1 Entonces
        libro.Prestar();
    FinSi
    Si devolver = 1 Entonces
        libro.Devolver();
    FinSi
    Escribir libro.EstaPrestado();
FinProceso
